export function Reauthentication({
  heading = "{{heading}}",
  actionLabel = "{{actionLabel}}",
  email = "{{email}}",
  showPassword = {{showPassword}},
  accent = "{{accent}}",
}) {
  return (
    <form style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: 20, borderRadius: 14, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <h3 style={{ margin: "0 0 6px", fontSize: 16 }}>{heading}</h3>
      <p style={{ margin: "0 0 16px", fontSize: 13, color: "#24143099" }}>Please re-enter your password to {actionLabel}.</p>
      <label style={{ display: "block", marginBottom: 16 }}>
        <span style={{ display: "block", marginBottom: 5, fontWeight: 600, fontSize: 13 }}>Password for {email}</span>
        <div style={{ position: "relative" }}>
          <input type={showPassword ? "text" : "password"} autoComplete="current-password"
            style={{ width: "100%", boxSizing: "border-box", padding: "9px 10px", paddingRight: 56, borderRadius: 8, border: "1.5px solid #24143030", font: "inherit" }} />
          <button type="button" aria-pressed={showPassword} aria-label="Show password"
            style={{ position: "absolute", right: 6, top: "50%", transform: "translateY(-50%)", border: "none", background: "none", cursor: "pointer", color: "#241430", fontWeight: 700, fontSize: 12, padding: "4px 6px" }}>
            {showPassword ? "Hide" : "Show"}
          </button>
        </div>
      </label>
      <button type="submit" style={{ width: "100%", padding: 10, borderRadius: 8, border: "none", background: accent, color: "#241430", fontWeight: 700, cursor: "pointer" }}>Confirm</button>
    </form>
  );
}
